   "「性质最接近金属」口径：最高疲劳强度、耐磨自润滑、使用温度 -40~120℃（宽口径，与「连续 90~100℃」并列）；缺点四条：长时间高温热分解、无自熄、抗酸差、成形收缩率大（经验值，AG51 工程塑料资料）",
