   "收缩量与制程：射出压力太低、保压/冷却时间不足、熔胶温度太高、模具温度太高、保压压力太低→过量收缩；温度-收缩矛盾律——料温高、模温高则收缩小但翘曲大（反之收缩大翘曲小），按制品主要矛盾取舍（《模流分析基础入门》第七章/《纠正注塑缺陷之完全手册》）",
