   "双色模设计依据《双色模介绍及设计规范》与《双色注塑模具设计 36 条经典经验分享》；实例见查鸿达《双色注射模具设计 10 个实例（经典案例）》；模塑件公差口径参 GB/T 47067-2026 / GB/T 14486-2008"
