   "斜顶角度 3°~10°（极限 12~15°），行程≈倒扣量/tanα，过斜顶出阻力大易烧",
   "滑块配套：铲基/耐磨板/压条；高速模加限位与复位检测",
   "每加一组侧抽：模具寿命降、周期 +5~15s、飞边点增多",
   "滑块/斜顶数量是模具报价的核心变量",
   "斜顶角度三口径并列（分歧照录）：3°~12°（《斜顶设计专题汇总》威虹，抽芯距大于产品扣位 3mm）/ 最大 7°、一般 5°（富士康《塑胶模具设计标准》3.2.1，受设备能力限制）/ 15° 以下尽可能小（威士茂）；tanα=斜顶行程/顶出行程、圆整为整数，斜顶行程=死角大小+≥3mm 最小安全量",
   "斜顶结构（《斜顶设计专题汇总》）：整体式紧凑强度好（小斜顶）、组合式易更换维修（大斜顶）；底端定位圆柱销式加工装拆易、T 型块式用于大/高精度件；除顶底面外需加工油槽；头部不得反斜度否则出模铲胶，须做运动校核防与顶针/骨位/其它斜顶干涉"
