   "斜顶面比胶位面低 0~0.10mm 合适（《注塑缺陷总结》）——三口径并列：平齐或低 0.1mm（威虹）/ 低 0.05mm 防拉伤（威虹规定 10）/ 低 0~0.10mm，高了出模铲胶；产品深且边上有斜顶时加台阶定位，缩呵式模尽量不用斜顶、必须用时采挂顶针式（威士茂）"
