   "滑块/顶针干涉：复杂模必做 UG 开合模运动仿真",
   "斜顶角度取上限又无润滑→烧死/断裂；斜顶头部做反斜度→出模铲胶；复杂模不做开合模运动仿真→斜顶与顶针/骨位/其它斜顶干涉（《斜顶设计专题汇总》威士茂条）"
