   "斜顶机构依据威士茂《模具基本标准·斜顶机构》与威虹《斜顶设计一般规定》（均收录于《斜顶设计专题汇总》）；行位/滑块规范见富士康《塑胶模具设计标准》3.1/3.2；侧向抽芯的模具要求以 GB/T 12554-2006（塑料注射模）为准"
