   "装配链公差叠加：零件公差沿装配方向逐环累计，判断间隙/干涉。极值法（worst case）保守简单；统计法（RSS）按分布叠加，可放宽公差。",
   "目的是用分析驱动公差分配：功能环收紧、非功能环放开。"
