   "尺寸偏差/发脆/破裂：尺寸变化本质是收缩差异（工艺不稳、结晶度变化、吸湿、模具变形）；脆化=降解分子链变短；破裂=降解、应力过大、混入不相容杂料，常在柱位或浇口（《注塑产品缺陷对照》/《模流分析基础入门》第八章）"
