   "爬电 > 间隙：同样电压爬电要求更长（表面路径）",
   "绝缘分类：基本/附加/双重/加强——双重绝缘=基本+附加（II 类照明产品）",
   "结构手段：加绝缘挡板/筋（抬高爬电路径）、开槽断爬电路径",
   "导电件之间也要：带电件↔可触及金属、L↔N（不同极性）、带电↔地"
