   "6063 与 6005 选材口径（中兴第 4 章）：6063 可挤复杂截面、中等强度；6005 强度硬度高于 6063 但成型困难、截面尺寸精度不易控制——复杂截面优先 6063",
   "空心截面用组合模焊合挤压（舌形模 / 平面分流模，中兴图 4-5/4-6）：焊合线落在哪由分流孔设计决定，图上要在非受力、非配合区给它预留位置"
