   "细长薄壁件按 6m 定尺挤出再切，损耗率约 3–8%。",
   "表面粗糙度按用途三档约定（中兴第 4 章）：装饰面 Ra0.8μm、非装饰面 Ra1.6μm、切削面 Ra6.3 或 3.2μm；喷砂纹 ZX-SB100(Al) 粗纹 / ZX-SB150(Al) 细纹，一般选 150 号"
