   "寿命加速：结温每升高 10K，L70 寿命约减半（Arrhenius 经验法则）",
   "L70 定义：光通量衰减到初始值 70% 的时间；标称值必须附测试条件（如 Tj=85℃ 或 Tc=25℃）",
   "蓝光芯片峰值波长随温升红移约 0.1 nm/K，导致色坐标偏移与显色指数变化",
   "恒流驱动下 LED 正向压降 Vf 随温度下降约 -2~-4 mV/K，可用 Vf 法反推结温"
