   "弹片选料：小电流信号与按键用 SUS301，需要同时导电并受压的端子接触簧片选 QSn6.5-0.1，插拔次数高时不要用普通黄铜",
   "散热件别用铜：同体积铜重 3.3 倍、成本数倍，只有热流密度极高的小面积热扩散片（LED 焊盘下方几十毫米见方）才值得用铜",
   "铜排折弯半径建议不小于 1 倍料厚，软态铜排可更小；反复折弯会加工硬化变脆，不能靠多折几次来找角度"
