   "ISO 14691:2008《石油、石化和天然气工业 机械动力传动用挠性联轴器 一般用途》——挠性联轴器选型与许用偏差的参考方法",
   "GB/T 1800.2-2020——轴孔配合公差带（H7/j6、H7/k6）取法；《机械设计手册》——联轴器特性与工况系数表",
