   "GB/T 15706-2012《机械安全 设计通则 风险评估与风险减小》——决定「失效后果」分项该取多少的法定依据，也是安全相关件的设计流程起点",
   "GB/T 700-2006《碳素结构钢》与 GB/T 1591-2018《低合金高强度结构钢》——Q235 / Q355 的屈服与抗拉下限，是取分母的源头数据",
   "VDI 2230 Blatt 1:2015-11《高强度螺栓连接的系统计算 第 1 部分：单个圆柱螺栓连接》——螺栓连接的安全系数与预紧力上限的权威算法",
   "GB/T 5080.1-2012《可靠性试验 第 1 部分：试验条件和统计检验原理》——想把「安全系数」换成定量的失效概率与置信度时用",
