   "试验台时就是钱：目标 MTBF 10 万小时、允许 0 故障时，单台要跑 11 年，所以必须用「多台并跑 + 加速应力 + 允许若干故障数」三招把周期压到 2–3 个月。",
   "试验费容易被漏算：高低温箱、温循与振动台按台时计费，一个 1000h 的环境试验台时费量级几千到几万元，要在报价里体现。",
