   "GB/T 2828.1-2012《计数抽样检验程序 第 1 部分：按接收质量限（AQL）检索的逐批检验抽样计划》——样本量字码、Ac/Re 与转移规则的唯一依据",
   "GB/T 12609-2005《电沉积金属覆盖层和相关精饰 计数检验抽样程序》——表面处理类来料（外观、厚度）的抽样口径，与 GB/T 2828.1 配合使用",
   "IPC-A-610《电子组装件验收条件》——电子件的缺陷分级与验收等级（Class 1/2/3），电子行业的判定标准常直接引用它",
