   "签样时把「不可接受的最好的那件」（下限）也做一套：实战中这一套比上限更常用，它挡住的是「差不多就放」的松动。",
   "样板要编号并上锁保管：现场出现的「临时样板」「别人给的样板」是客诉的主要来源，样板丢失即失效、需重新签样。",
   "供应商送样承认时，让供应商也留一套同源样板：后续来料争议可以回到同一标准比对，避免「各说各话」。",
   "把检验规范做成「一页版」放在工位：项目、方法、判定、频次四列，配实物样板与量具照片，比一本几十页的文件更有执行力。"
