   "审厂最常被开的两条：控制计划里写的量具现场找不到、反应计划里写的责任人已经离职。所以每次更新后要现场核对量具实物、校准状态与人员。",
   "电子与装配类企业的控制计划必须包含「防错装置有效性验证」条目，每班用坏件挑战一次并留记录——这是 IATF 审核的重点，也是最能体现体系真实运行的一项。",
