  "PS/HIPS 收缩率：PS 0.2~0.7%（常取 0.4%，熔化 180~280℃、模温 40~50℃；经验值《塑胶原料选择》）；0.4~0.8%（另一处 0.3~0.8%）与约 0.45%；HIPS 0.2~0.6%（线胀系数 0.000034~0.00021/℃、HDT 96℃；经验值《各种塑胶原料之注塑成型条件》）",
