window.KB_MEMO = {
 "ABS": "综合性能最均衡，好喷好镀不耐晒——室内件首选，户外必换 ASA。",
 "PC（聚碳酸酯）": "透明又抗冲，怕溶剂怕应力——透明结构件选它，别拿酒精擦。",
 "PP（聚丙烯）": "便宜耐化学、能弯百万次——活铰链首选，但收缩大缩水难控。",
 "PMMA（亚克力）": "透光最好的塑料，又脆又怕划——导光/外观件用它，受力位别用。",
 "PVC（软/硬）": "软硬都能做，价低但怕热怕老化——线材包胶可用，外壳结构件少用。",
 "TPU": "软而有弹性、耐磨耐油——包胶防滑垫常用，包硬胶要验证相容性。",
 "TPE/TPR": "像橡皮的塑料，能回收比硅胶便宜——手感件替代硅胶，耐温不如硅胶。",
 "液态硅胶 LSR": "耐温 -50~200℃、食品级柔软——防水密封圈与按键首选。",
 "固态硅胶（HTV）": "硅胶的压制版，成本低但毛边多——大批量小件用，模具要做撕边。",
 "环氧树脂（EPOXY）": "透明可浇注能包埋，硬而脆——树脂面罩/工艺品，厚件放热会开裂。",
 "不饱和聚酯树脂（水晶树脂）": "便宜的水晶效果，收缩大易黄变——低价树脂件用，别做精密配合。",
 "POM": "又硬又滑能自润滑——齿轮滑轨首选，但粘接性差别指望粘住。",
 "PA（尼龙）": "耐磨耐油但爱吸水——吸湿会涨尺寸，配合要留余量。",
 "阻燃等级 UL94": "从 HB 到 5VA 越来越难烧——外壳至少 V-0，注意厚度与落球要求。",
 "收缩率": "缩水不是缺陷是材料天性——模具按收缩率放，不同料能差三倍。",
 "环保 RoHS/REACH": "出口欧美的入场券——高风险物料先要环保报告，再谈价格。",
 "熔融指数（MFI）": "MFI 高好流动但强度低——薄壁件要高 MFI，结构件反过来。",
 "玻纤增强塑料（GF）": "加玻纤刚度翻倍，但翘曲大外观差——外观件慎用。",
 "ASA / 耐候PC": "户外不黄变的 ABS——户外件标配，贵一截但省了售后。",
 "塑料物性表解读": "先看三个数：收缩率、耐温、缺口冲击——其余都是参考。",
 "再生料 rPC / rABS": "便宜但有黑点与性能波动——非外观非承力件可用，必须验批次。",
 "材料替代降本路径": "降本先降料再降工艺——ABS→PS、PC→PC+ABS，但强度要重验。",
 "注塑成型": "塑料成型的主力军——批量过五千就上钢模，模具是一次性投入。",
 "双色注塑": "一次成型两色两料，免组装免喷涂——模具贵，量不够别碰。",
 "搪胶（滚塑搪胶）": "空心软胶体的唯一解——夜灯软壳用它，壁厚均匀靠工艺兜。",
 "树脂一体成型（浇注）": "一次浇出通透树脂件——氛围灯树脂体常用，重点控排气与放热。",
 "压缩模塑（硅胶模压）": "硅胶件的标准工艺——毛边靠模具撕边设计解决。",
 "挤出成型": "长条形连续出料——型材线材管材，断面定死不能变。",
 "吹塑": "中空一体成型——水瓶、浮球、中空容器，壁厚不均要接受。",
 "真空复模（小批量）": "硅胶模翻几十件——验证阶段用，量上去必换钢模。",
 "3D打印": "手板最快的路——外观验证够用，强度别当真。",
 "微发泡 MuCell": "注气减重又减缩水——厚壁件好用，表面流纹要接受。",
 "气辅成型": "内部吹气做中空——粗大把手支架减重防缩水。",
 "脱模斜度": "没有斜度就没有注塑——光面 0.5~1°，纹越深斜度越大。",
 "壁厚设计": "均匀是王道，变化别超 25%——厚了缩水，薄了欠注。",
 "加强筋": "筋厚取主体壁厚的 0.5~0.6 倍——太厚反缩水，高度别超 3 倍壁厚。",
 "BOSS柱（螺丝柱）": "柱外径约等于内孔直径的两倍——太厚缩水，加肋支撑别加厚。",
 "止口（配合结构）": "遮缝靠止口，导向也靠它——留 0.1~0.2 间隙，长度 3 倍壁厚够。",
 "卡扣设计": "一次装配免螺丝——悬臂根部必须圆角，插拔次数决定选料。",
 "公差与配合": "该松的松该紧的紧——先定基准再标公差，别全给 ±0.1。",
 "美工线": "分型面不好看就藏进美工线——0.3~0.5mm 凹槽，主动设计别被动接受。",
 "按键结构": "手感靠行程与力度不靠玄学——1.5~2.5N 力度，0.3~0.6mm 行程。",
 "线缆走向与出线": "出线口必须做应力消除——直接拉线会拉断焊点。",
 "电池仓设计": "先定电池规格再画仓——公差留够，弹片要防反接。",
 "转轴/阻尼结构": "转轴要寿命，阻尼要一致——寿命试验是唯一真理。",
 "防尘防水结构": "IP 靠密封圈压缩率——压 20~30%，密封面要平要光。",
 "跌落防护": "跌落看角与棱不看平面——薄弱处加厚或加缓冲，落点优先保护。",
 "DFMEA 分析": "提前把风险写出来——严重度×频度×探测度打分，高分的先解决。",
 "装配工艺性（DFA）": "能少一颗螺丝就少一颗——零件数方向工具都要往下压。",
 "过盈配合压装": "过盈量决定压装力与开裂风险——塑料件过盈要小，金属件可大。",
 "弹簧选型（扭簧/压簧）": "先算力再选簧——注意疲劳寿命与安装预压量。",
 "齿轮传动基础": "齿轮看模数、中心距、齿隙——塑料齿轮靠齿隙存油脂。",
 "防拆螺丝": "防拆只防君子——要真防拆得配合超声波焊接。",
 "减震设计进阶": "减震要软但必须限位——纯软会晃，纯硬会传振。",
 "滑动/拨动机构": "滑动靠导轨与限位——行程末端必须有硬限位，别让塑料对磨。",
 "自攻螺丝": "塑料自攻要控底孔——底孔≈螺钉径×0.8，柱外径×2，拧两次就滑牙。",
 "热熔螺母（铜嵌件）": "要反复拆装就上铜螺母——热熔温度与埋入深度是关键。",
 "超声波焊接": "同种料才能熔在一起——熔接线设计定成败，异种料别想。",
 "热熔/热铆": "铆柱压扁做固定——铆柱径高按经验比，压太狠直接裂。",
 "双面胶/背胶": "粘接看面积与表面能——PP/PE 这类低表面能料必须先处理。",
 "卡勾锁扣": "不需要拆的才用卡勾——一次锁死，拆就断，设计时就想清楚。",
 "机米螺丝与螺纹胶": "小螺丝防松靠胶——点胶量要少，螺纹胶分可拆与不可拆。",
 "分型面（Parting Line）": "分型面决定外观与模具难度——先定分型再画结构，别反过来。",
 "滑块与斜顶": "侧面有倒扣就得上行位——滑块越多越贵越易坏，能改设计就先改设计。",
 "顶针与浇口": "顶针顶在产品背面——顶针避开外观面，浇口位置决定熔接线。",
 "模具钢材与寿命": "产量决定钢材——几万模用 P20，几十万模上 NAK80 / S136。",
 "T0/T1 试模与检讨": "T0 看结构、T1 看尺寸——试模别带情绪，按清单逐条对。",
 "DFM 检讨": "开模前把话说清楚——DFM 报告逐条签字，后面才不扯皮。",
 "公差分析（叠加）": "尺寸链最坏情况必须算——别指望「应该差不多」。",
 "颜色与外观标准": "颜色必须有标准板——色差 ΔE≤1.5，A/B/C 面分级要求。",
 "注塑常见缺陷与对策": "缩水加保压、飞边降压力、熔接痕提模温——对症下药别乱调机。",
 "模流分析 Moldflow": "模流能提前看见熔接线——大件外观件必做，小件可省。",
 "热流道模具": "热流道省料省周期——但流道要控温，多模穴才划算。",
 "排气设计": "排气槽 0.02~0.03mm——深了飞边浅了烧焦，料流末端必排。",
 "SPCC / SECC 冷轧板": "机箱铁皮的标准选择——SPCC 便宜要防锈，SECC 自带镀锌。",
 "SUS304 不锈钢": "不锈但会带磁会发亮——要焊接要防腐就选它，成本是铁皮四倍。",
 "5052 / 1060 铝板": "5052 强度好能折弯——1060 更软更便宜，装饰件够用。",
 "ADC12 压铸铝": "压铸能做复杂形体——散热器结构件常用，气孔要控制。",
 "6063 / 6061 铝型材": "型材先看断面——6063 好挤压做外观，6061 强度高做结构。",
 "镀锌板 vs 铝板选型": "要强度防腐选镀锌，要轻要散热选铝——表面处理成本别忘算。",
 "金属件防腐": "盐雾是硬指标——室内 24h，室外 48~96h，海边再翻倍。",
 "不锈钢 304 vs 201": "304 才真不锈——201 便宜但会锈，出口件别碰。",
 "常用钣金料厚系列": "0.5 / 0.8 / 1.0 / 1.2 / 1.5 / 2.0——规格越少越好采购。",
 "钣金折弯最小半径": "最小内 R 约等于料厚——R 太小会裂，料越硬 R 越大。",
 "钣金展开与折弯系数": "展开要减料，K 因子约 0.4——展开算错装配就装不上。",
 "冲孔与翻边攻牙": "冲孔离折弯线要够远——太近会变形，翻边够高才够牙。",
 "激光切割": "切缝 0.1~0.2mm 无毛刺——打样首选，量大了改模具。",
 "CNC 数控加工": "精度高成本也高——小批手板与精密件用，批量必换工艺。",
 "氩弧焊/点焊": "点焊快氩弧焊美——外观件氩弧焊，结构件点焊够。",
 "压铆螺母/螺柱": "钣金攻牙不如压铆——压铆强度稳定，但要控板厚与孔径。",
 "喷油（喷漆）": "最通用的上色方式——附着力靠前处理，掉漆先查清洁与底漆。",
 "电镀": "金属质感最强——电镀件要设计挂点，镀层厚薄不均会露底。",
 "真空镀（NCVM）": "不导电的金属感——做透光金属漆效果，须加保护漆。",
 "丝印 / 移印": "平面用丝印，曲面用移印——附着力靠火焰或等离子处理。",
 "激光镭雕": "不掉字的标识方式——深浅可调，透光件能做透光字符。",
 "咬花（蚀纹）": "蚀纹有标准，VDI 数字越大越粗——蚀纹面脱模斜度必须加大。",
 "IMD/IML 模内装饰": "一次成型带图案，耐磨不怕刮——但模具与良率要求高。",
 "阳极氧化": "铝的专属上色——只能做铝，氧化膜绝缘，导电处要留触点。",
 "粉末喷涂": "厚膜耐候强——户外金属件首选，细腻度不如喷漆。",
 "金属拉丝": "质感靠纹理方向——拉丝方向要一致，拉完必须加保护。",
 "GD&T 形位公差": "形位公差管形状与位置——比尺寸公差更能表达真实意图。",
 "基准体系（A/B/C）": "基准是测量的起点——先定 A 再定 B/C，基准错了全盘皆错。",
 "表面粗糙度 Ra": "Ra 越小越光——注塑模 0.4~0.8 够用，要求过高白花钱。",
 "孔轴公差配合": "优先用基孔制——H7/g6 间隙、H7/p6 过盈，记住这几个够日常。",
 "注塑件公差标准（GB/T 47067）": "注塑件别随手给 ±0.05——按现行 GB/T 47067-2026（原 GB/T 14486）选 MT 等级，不要拍脑袋。",
 "制图投影与视图规范": "第一视角还是第三视角必须写清——国内第一视角，出口图注意切换。",
 "CAD 建模与出图流程": "先建骨架再建零件——改规格只动骨架，改一处全联动。",
 "工程变更 ECN/ECR": "变更必须留痕——ECN 编号、版本、生效日期一个都不能少。",
 "装配图与爆炸图": "装配图讲关系，爆炸图讲顺序——爆炸图要有编号与 BOM 对应。",
 "公差标注常见错误": "标了一堆公差却没标基准——公差要能测量才有意义。",
 "配光基础": "光要往哪去就设计哪——角度、均匀度、效率三者互相拉扯。",
 "扩散件（PC/PMMA光扩散）": "扩散剂越多越柔越损失——透光率与遮蔽性要找平衡。",
 "透镜（一次/二次）": "一次光学在 LED 封装上，二次光学在外加透镜上——先做一次再做二次。",
 "反射杯": "反射效率看镀层与角度——镀铝约 85%，抛光可达 95%，按成本选。",
 "遮光角与防眩": "遮光角越大越不刺眼——30° 起步，越大越防眩但效率下降。",
 "混光腔": "RGB 要混均匀必须给距离——距离不够就会看到色斑。",
 "导光板（LGP）": "网点决定均匀度——网点密度从远端到近端递增。",
 "色温与显色指数（CRI）": "色温看氛围，CRI 看真实——家用 CRI≥80，阅读≥90。",
 "频闪与护眼": "频闪看波动深度——＜5% 算合格，无频闪芯片贵但值。",
 "光通量/光效/照度": "流明是总量，勒克斯是密度——光效＝流明÷瓦，越高越省电。",
 "蓝光危害 RG 等级": "RG0 最安全——儿童灯必须 RG0，成人灯不超 RG1。",
 "光学件卡位与公差": "光学面不能碰——Lens 到 LED 的距离公差直接决定光斑。",
 "LED热阻链路": "热阻像电阻串联——结到壳、壳到板、板到环境，最短板决定一切。",
 "铝基板（MCPCB）": "LED 散热的标配——绝缘层是热阻瓶颈，选高导热才有意义。",
 "导热界面材料": "界面是热阻黑洞——硅脂 1~3 W/mK，导热垫 1~6，别省这一层。",
 "塑料散热设计": "塑料不导热就扩大面积——加金属嵌件或做薄壁大面辐射。",
 "自然对流布置": "热气往上走——进风口在下出风口在上，别挡住对流路径。",
 "热仿真基础": "仿真先校核材料参数——参数错了算得再准也没意义。",
 "散热器鳍片设计": "鳍片越密越好？错——间距小于 6mm 就没风了。",
 "GB 7000 灯具安全标准": "国内照明产品的安全底线——爬电距离、温升、结构强度都在里面。",
 "3C认证": "国内上市的前提——没有 3C 不能卖，认证要提前半年排期。",
 "CE / ERP / RoHS": "出欧盟三件套——CE 管安全，RoHS 管材料，ERP 管能效。",
 "UL / ETL（北美）": "北美要 UL 或 ETL——UL 认可度高但贵，ETL 便宜且等效。",
 "IP防护等级": "第一位防尘第二位防水——IP54 户外够用，IP67 能泡水。",
 "爬电距离与电气间隙": "高压必须留距离——250V 爬电 ≥3.2mm，潮湿环境还要加。",
 "儿童安全相关法规": "儿童灯要求最严——不能有可拆小件，不能夹手。",
 "蓝牙/无线认证": "带无线就要认证——SRRC（国内）＋ FCC（美）＋ CE-RED（欧）。",
 "温升测试": "温升不超限就安全——可触及表面 ≤70℃，绕组温升 ≤75K。",
 "Class II 双重绝缘": "双重绝缘不需要接地——II 类照明产品的标志就是回字形。",
 "跌落测试": "跌落看角与棱——1.2m 混凝土地面，6 面 3 棱 1 角摔够。",
 "高低温循环": "冷热交替考验材料——-20~60℃ 循环，重点看开裂与变形。",
 "老化寿命测试": "老化要按倍率折算——常温 1000h 约等于实际几年，看光衰曲线。",
 "振动与运输测试": "运输振动最伤焊点——ISTA 3A 是电商包装的标准参考。",
 "盐雾测试": "盐雾看时间——24h 室内，48~96h 室外，海边再翻倍。",
 "拉扭力测试": "拉力扭力定装配可靠性——自攻螺丝的拉出力是验证核心。",
 "IP防水测试": "防水按等级测——IPX4 淋雨，IPX7 泡 30 分钟。",
 "按键寿命测试": "按键按够 5 万次才算合格——按不到就是结构或选料的问题。",
 "开合/旋转寿命测试": "转轴寿命是硬门槛——1 万次开合后阻尼衰减不超 30%。",
 "彩盒结构与瓦楞选型": "小盒用 E 楞，大箱用 BC 楞——楞型决定强度与厚度。",
 "EPE/EVA/纸浆内衬": "内衬是防摔的关键——EPE 便宜，EVA 高级，纸浆环保。",
 "吸塑包装": "吸塑先看样板与模具费——小批量贵，量大才摊得薄。",
 "ISTA 运输测试标准": "ISTA 是运输的通行证——3A 电商件，2A 一般运输。",
 "堆码与仓储": "堆码高度决定纸箱抗压——湿度一上来抗压还会衰减约一半。",
 "说明书与标识": "标识是法规要求——警告语、型号、认证标志一个都不能少。",
 "包装装载率与电商物流": "装载率决定运费——装箱体积降 10%，运费就省 10%。",
 "脆值G与缓冲计算": "脆值 G 决定缓冲厚度——G 越小越脆，缓冲就要越厚。",
 "BOM 表管理": "BOM 是成本的账本——层级、版本、单位、损耗都要清楚。",
 "成本构成（料工费）": "成本＝料＋工＋费——塑料件料占 50~70%，金属件工占比高。",
 "DFC 设计降本": "降本要在设计阶段做——量产后只能抠 5%，设计阶段能省 30%。",
 "开模报价与模穴数": "模穴数决定单件成本——量大加穴，量小别硬上。",
 "量产爬坡与良率": "良率爬坡要时间——前三个月 70~90%，报价要留爬坡成本。",
 "打样与手板": "手板贵但省时间——3D 打印几百，CNC 几千，真空复模几百。",
 "供应链交期与选点": "交期是隐形风险——单一供应商是大忌，关键料至少双点。",
 "塑料件报价估算": "估价＝料重×料价÷良率＋加工费——用来快速判断报价是否离谱。",
 "模具摊销计算": "摊销＝模具费÷总产量——量大摊销小，但别忘了模具还有寿命上限。",
 "报价单核对要点": "报价单看四项——单价、模具费、MOQ、付款方式。",
 "PC/ABS 合金": "PC 的强度 ABS 的脸——折中方案，但别指望它耐候。",
 "常用塑料牌号对照": "只写材料名等于没写——材料 + 厂牌 + 牌号，缺一不可。",
 "塑料耐化学性速查": "先问会接触什么，再谈选什么料——PC 最怕的就是那瓶酒精。",
 "导热塑料": "导热塑料是「摊热」不是「散热」——差铝合金两个数量级。",
 "嵌件注塑（Insert Molding）": "要牢靠就提前埋进去——嵌件注塑比后装螺母牢一倍。",
 "硅胶包塑（双色硅胶）": "硅胶和硬胶不粘——靠燕尾槽咬住，不靠胶水粘住。",
 "塑料激光焊接": "上透下黑，激光穿过熔在中间——无飞边无振动的密封方案。",
 "灯罩固定方式": "要拆就别超声，要防拆就别卡松——四条路各有各的代价。",
 "透镜固定与卡位": "定位、限位、预压，缺一样光斑就偏——透镜固定是三件套。",
 "导线固定与线槽设计": "线不能悬空——槽、扣、倒角、护套，四件套缺一不可。",
 "防水透气膜（ePTFE）": "水进不来、气出得去——密封壳体的呼吸阀，别拿无纺布凑数。",
 "螺钉柱防滑牙设计": "底孔 0.8 倍、柱径 2 倍、柱壁 1mm——三个数管住滑牙。",
 "线束固定与热缩管": "焊点不包热缩管等于裸奔——安规第一眼就看这个。",
 "多腔模具与流道平衡": "一模多腔不是复制——流道不平衡，出来的件就不是一个件。",
 "模具钢热处理与表面强化": "要亮的选不锈钢，要耐磨的上氮化——透明件先看抛光性。",
 "灯具配光测试": "积分球管总量，分布光度计管方向——配光曲线只能靠后者。",
 "灼热丝与球压测试": "灼热丝考抗引燃，球压考抗形变——都是塑料件在挨考。",
 "恒温恒湿与冷热冲击": "湿热考吸湿老化，冲击考膨胀不匹配——后者专治金属嵌件。",
 "供应商评估与选点": "选供应商是选风险，不是选价格——关键件必须两家。",
 "样品承认流程": "签样是量产的合同——没签样，出了争议谁也说不清。",
 "驱动电源安装与固定": "驱动是灯的第二个热源也是高压源——要能换、要散热、更要留出爬电距离",
 "磁吸结构与磁铁固定": "磁吸的吸力看壁厚——隔 1mm 剩七成、隔 3mm 只剩三成",
 "接线端子与压线结构": "拉力给壳体、导电给端子，剥皮别露铜",
 "连接器与端子选型": "会动的部位必须带锁扣；接触不良多半出在压接不在连接器",
 "轨道灯导电结构": "轨道要防呆——能反装就一定会有人反装",
 "触摸按键结构": "电容式怕金属、弹簧式怕公差，两条路的死法不一样",
 "O 圈与密封槽设计": "密封靠压缩量，不靠胶水——压缩 20~25% 刚好，过了就永久变形",
 "驱动灌胶与防水": "灌胶是用材料换结构——省了密封圈，代价是不可维修",
 "保护接地与接地连续性": "接地不是让外壳不带电，而是让故障电流大到能跳闸——电阻 ≤0.5Ω 才算接上了",
 "认证送样与准备清单": "送样状态必须等于量产状态，否则认证等于白做",
 "常见认证不合格项与整改": "九成不合格集中在爬电、温升、强度、灼热丝、标签这五处",
 "光衰与寿命设计": "结温每升 10℃ 寿命减半——光衰问题说到底还是散热问题",
 "自然对流换热能力估算": "自然对流三个数：面积、朝向、温升——1W 大约要 20~30 平方厘米",
 "温度对 LED 光效与寿命的影响": "温度一升，光是暗的、命是短的——结温每高 10K，寿命砍一半",
 "驱动电源热设计": "驱动里最先死的不是芯片是电容——温度降 10K，寿命翻一倍",
 "热测试方法与测点布点": "测点、固定、稳态三样不变才能比；发射率不设，热像仪就是个体温计",
 "过温保护与降额设计": "保护点要比材料耐温低 20K 才算保护——动作时零件没坏才叫成功",
 "密封灯具的散热矛盾": "越密封越不散热——全塑壳密封灯，功率上限只有 3~5W",
 "导热灌封与填充": "灌封的导热靠薄、匀、无泡——一个气泡顶一层棉被（空气只有 0.026）",
 "热应力与材料匹配": "膨胀差 0.37mm 不会自己消失，只能靠让位孔或弹性件吃下去",
 "铜与铜合金": "导电用紫铜、切削用黄铜、弹性用磷青铜——铜铝接触必隔开",
 "锌合金压铸（Zamak 3 / 5）": "锌合金模便宜、件精细、重量翻倍，但受不住长期受力",
 "不锈钢弹片（SUS301）与弹簧钢": "301 的弹性是轧出来的，折弯别小于半个料厚，硬度档位要写清",
 "压铸铝的去应力与变形控制": "压铸件的应力要「先放再切」——时效一定放在精加工之前",
 "铝合金阳极氧化的色差与封孔": "氧化色差靠同炉号同批，封孔决定户外能撑几年",
 "热浸镀锌 vs 电镀锌": "室内电镀锌、户外热浸镀、高强紧固件走达克罗",
 "金属牌号对照（GB / ASTM / JIS）": "牌号只是名片，靠得住的是证明书加成分复检",
 "不锈钢钝化与焊后处理": "不锈钢靠膜不靠钢——焊后酸洗加钝化，膜重建了才不锈",
 "钣金折弯的回弹控制": "R/t 越大越弹、料越硬越弹；控回弹三招——过弯补偿、压料校形、减小 R/t。",
 "PE（聚乙烯）": "PE 又滑又印不上、收缩还大——想印就先电晕，做倒扣倒是不用怕。",
 "HIPS（高抗冲聚苯乙烯）": "HIPS 是「便宜版 ABS」——能做扣位和自攻柱，但别碰 85℃ 以上和户外。",
 "AS/SAN（苯乙烯-丙烯腈共聚物）": "AS 是「透明版 ABS」——能擦酒精，但一受力就脆。",
 "塑料回收标识（三角标 1–7）": "三角标 7 不等于 PC——它只是「其他」这一筐。",
 "塑料鉴别方法（密度与燃烧）": "先浮沉再烧一烧——气味加密度交叉验，单靠鼻子最容易被增塑剂骗。",
 "塑料助剂与填充剂": "树脂定基本性能，助剂定能不能用——同一牌号加不同助剂就是两种材料。",
 "转角与圆角设计（R 角）": "圆角取壁厚的一半到一倍半——省应力也省脱模力，但别做在分型面上。",
 "支柱套（地柱 / Boss holder）": "螺丝头要藏起来——凹坑至少 3mm 深，四周还得倒 R1.0 以上。",
 "零件间隙（虚位）": "不动的 0.1–0.2、要动的 0.3–0.5——塑胶件千万别按金属件的间隙配合。",
 "六角孔配圆 Pin（紧钉定位）": "要定位就用六角孔配圆柱——不留虚位不做斜度，但导入角必须有。",
 "六角螺母的装配（热熔 / 冷打）": "要反复拆装就埋金属螺母——六角防转，热熔或冷打防掉。",
 "叉骨（止口管位骨）": "叉骨间距不能大——塑胶会弹，放太疏照样面刮。",
 "插穿位与碰穿位": "插穿最少 3°——少了合模就啃钢，模具寿命从这里开始掉。",
 "孔与凹陷设计": "记住 2、3、3/4 倍孔径——孔离边太近，裂的就是那片薄肉和薄钢。",
 "成形螺纹（塑胶直接成型螺纹）": "塑胶螺纹别做细牙、别做长——末端留 0.8mm 平坦，否则崩的是模具。",
 "底刮与面刮（段差控制）": "宁可面刮不可底刮——面壳做略大一点，手感是往下顺不是往上顶。",
 "支承面设计（凸点 / 凸环）": "大平面永远不平——支承改成三四个小凸点，晃动量立刻可控。",
 "旋钮与推钮设计": "推钮孔 = 行程 + 钮 + 2mm——算少了推不到底，算多了露出内脏。",
 "橡胶按键（导电胶）设计": "橡胶钮防连动靠「压紧非按键区」，不是靠拉开按键间距。",
 "PCB 与塑胶件的装配方式": "PCB 固定先看开模方向——垂直最省零件，夹角就得加支架或补胶件。",
 "注塑机组成与选型": "选机台先锁模力再注射量——而且注射量只用到一半到七成半。",
 "注塑工艺参数体系（温度 / 压力 / 速度 / 时间）": "温度管能不能流、压力管填不填满、时间管稳不稳——别拿一个参数治所有病。",
 "注塑调机方法（参数调校）": "调机就是找短射点和毛边点的中间——别凭手感，凭制品。",
 "换坷位设计（换镶件 / 换 CORE）": "换 CORE 就是「一套壳养多个型号」——差异全部塞进镶件里才省钱。",
 "压延成型": "压延是「用辊隙定厚」——只做等厚片材，不做立体结构。",
 "塑胶电镀件设计": "电镀件别做大平面和直角——挂点留好、圆角倒够，镀出来才不结瘤。",
 "变压器位与散热孔设计（火牛位）": "火牛柱是跌落测试的重灾区——柱要加筋，底部要留空隙开腰型散热孔。",
 "家用电器分类与防触电保护方式": "新产品只按 I 类、II 类、III 类定位——0 类和 0I 类是老标准的说法。",
 "齿轮传动选型（直齿 / 斜齿 / 行星）": "扭矩定大小、噪声定齿形、精度定背隙——斜齿要用轴承吃掉那份轴向力。",
 "齿轮模数与齿数设计要点": "模数管强度、齿数管转速比——按标准模数选，中心距是算出来的不是凑出来的。",
 "蜗轮蜗杆与自锁": "自锁靠 γ ≤ ρ′，效率也就丢了——要省电就加抱闸，别指望蜗杆又锁又省。",
 "带传动选型（同步带 / V 带）": "要准用同步带、要便宜用 V 带；同步带别绷太紧，轴承按三次方记仇。",
 "链传动选型与张紧": "齿数不少于 17、留 1%–2% 垂度、伸长 3% 换链条——链轮要跟链条一起换。",
 "丝杠传动（梯形丝杠 / 滚珠丝杠）": "梯形丝杠能自锁但效率只有四成，滚珠丝杠高效但断电会掉——垂直轴一律抱闸。",
 "齿轮齿条机构": "转一圈走 πmz，拼接要打销钉——齿条不自锁，垂直轴必须配抱闸。",
 "凸轮机构设计": "压力角别超 30°、滚子别大于 0.8ρ、弹簧要压得住惯性——高速用摆线规律。",
 "连杆机构（四杆 / 曲柄滑块）": "先算格拉肖夫再画图：最短 + 最长 ≤ 其余两杆之和，传动角别低于 40°。",
 "轴承选型与寿命计算": "先算 L10 再定尺寸，配合作 k6/H7——塑料壳里装轴承，必须加金属嵌件。",
 "轴系设计（轴向定位与配合）": "先定位再定尺寸：圆角必须小于轴承倒角，卡簧只定位不承载——油封轴颈要磨硬。",
 "联轴器选型": "定位轴用膜片 / 波纹管求零背隙，普通轴用梅花省成本——选完必须打表对中。",
 "直线导轨与滑块": "导轨精度七分靠基面：先锁基准侧再装从动侧，一个滑块扛不住悬臂。",
 "减速机构与减速比": "扭矩靠比数放大，但先看热功率：垂直轴一律加抱闸，别赌蜗杆自锁。",
 "应力集中与过渡圆角": "圆角不是外观问题——R0.2 改成 R2，寿命常常翻几倍，而且不花钱。",
 "安全系数取值": "安全系数是分项乘出来的，不是拍出来的——乘出 2 之前先说得清每一乘的依据。",
 "刚度与变形控制": "跨距是挠度的头号杀手——能加支撑就别加厚，能加筋就别换料。",
 "疲劳强度与疲劳寿命": "疲劳看的不是峰值应力而是应力幅——所以预紧能把螺栓救活，圆角能把轴救活。",
 "疲劳缺口系数与表面影响": "铸铁不怕缺口、高强钢最怕——所以铸铁件别死磕圆角，高强钢件必须喷丸。",
 "屈曲与失稳": "细长件只认 E 和 I，不认强度——换个更硬的钢一点用没有，加个中间支撑才翻四倍。",
 "蠕变与应力松弛": "塑料是常温就开始蠕变的——按瞬时模量算刚度，等于默认零件只用一个星期。",
 "冲击与跌落力学": "跌落不是强度问题而是「时间太短」——能把变形时间拉长的结构，才是抗跌结构。",
 "断裂韧性与脆性失效": "强度越高越脆——加厚和高强钢常常是脆断的帮凶，真该改的是结构和表面。",
 "有限元分析（FEA）基础": "FEA 给方向和相对比较，试验给结论——看见尖角上那个红点，先想想它是不是奇异点。",
 "简化强度校核（梁 / 板 / 悬臂）": "九成件手算就够——先看清是悬臂还是简支（差 16 倍），再谈别的。",
 "断口判读与失效分析": "断口是唯一不可复制的证据——先拍照再动手，扩展区占多少决定整改方向。",
 "焊接工艺选型（电弧 / 激光 / 电阻 / 钎焊）": "薄板批量上点焊，外观件上 TIG，精密件上激光，异种材料上钎焊。",
 "焊缝布置与坡口设计": "坡口是让电弧够得到根部——V 形比 X 形多耗一倍填充金属，能双面就别单面。",
 "焊接变形与残余应力控制": "焊变形是先减热、再反变形、后刚固定——校形是最后的补救，不是常规工艺。",
 "焊接质量检验（VT / UT / RT / MT / PT）": "不锈钢不做磁粉，裂纹要靠超声——探伤前先做目视，返修后必须重探。",
 "焊接工艺评定与焊工资质": "先有 PQR 才写 WPS——换厂、换气、换板厚都得重评，纸面对不上等于没有。",
 "异种金属焊接与电偶腐蚀": "异种金属两道坎——焊不牢（脆性相）和锈得快（电偶），先绝缘再谈焊接。",
 "粘接接头设计（搭接 / 剪切 / 剥离）": "胶怕撕不怕剪——让胶层受剪、让机械结构挡剥离，加宽比加长更管用。",
 "结构胶选型（环氧 / 丙烯酸 / 聚氨酯 / 硅酮）": "要强度找环氧、要韧找丙烯酸或聚氨酯、要耐候耐温找硅酮——先问节拍再问强度。",
 "表面处理与粘接强度": "粘不牢先别怪胶——油、硅、水在界面上，达因笔一划就知道。",
 "胶接耐久性与老化": "胶接失效多半是湿热把界面泡开了——按老化后的保持率验收，别信初始值。",
 "静密封形式选型（垫片 / O 圈 / 密封胶 / 金属密封）": "能上 O 圈就别打胶——胶靠人手上，O 圈靠沟槽尺寸，后者才可复现。",
 "动密封选型（油封 / 唇形密封 / 格莱圈）": "动密封不怕微渗，怕唇口烧掉——轴别太光、别带螺旋纹，装配别划伤。",
 "密封压缩量与压缩永久变形": "漏不漏看压缩量，不看拧多紧——静密封 15–25% 是铁律，公差链要一起算。",
 "密封面粗糙度与平面度要求": "密封面别追求最光——O 圈要 0.4–1.6μm，平面度差比粗糙度超差更致命。",
 "密封沟槽尺寸与公差": "沟槽三件事——深度定压缩、宽度留溶胀、倒角别切圈；先选标准 O 圈再画槽。",
 "法兰与端面密封设计": "法兰漏不漏看螺栓排布——间距要密、靠近密封面、对角分步拧，垫片不回弹就早晚漏。",
 "气密与检漏方法（压降 / 氦检 / 水检）": "先定允许漏率再选方法——压降查大漏、氦检查微漏，温度不等同就是自欺欺人。",
 "呼吸与压力平衡（透气膜 / 呼吸阀 / 凝露控制）": "封得太好也会漏——温度一变腔体就得呼吸，先留条透气的路，再谈防凝露。",
 "接头与线缆入口密封": "线缆过孔是密封短板——密封段落在护套上、留应力释放、夹紧范围要包住线径。",
 "密封失效排查（渗漏 / 冷凝 / 微漏）": "先分清渗漏、冷凝还是微漏——水在缝隙里是漏进来，水在冷面上是凝出来，方向错了白改。",
 "电偶腐蚀与异种金属接触": "异种金属一碰水就出事——不锈钢永远是「坏人」，铝和镀锌件要垫、要封、要厚镀。",
 "缝隙腐蚀与点蚀": "缝宽 0.05 mm 最要命——能不搭接就别搭接，垫片别用吸水的，焊完必须酸洗钝化。",
 "应力腐蚀开裂": "三件凑齐才出事：敏感材料 + 氯离子 + 拉应力——温度降到 60 ℃ 以下、残余应力退掉，比换材料便宜。",
 "涂层防腐体系（ISO 12944）": "涂层是三层配套不是一层厚漆——前处理没做到 Sa 2½，膜再厚也白搭。",
 "不锈钢在氯离子环境中的选材": "海边别用 304、热水别用奥氏体——氯离子挑牌子，温度挑命。",
 "铝合金的腐蚀与防护": "铝的氧化膜又薄又多孔——不加绝缘垫就被不锈钢吃掉，不加喷涂就顶不住海边。",
 "塑料老化的机理与防控（紫外 / 湿热 / 臭氧）": "紫外打断链、湿热加速度、臭氧专挑橡胶——户外件以 ASA/PC 为底，UVA 配 HALS，别只加一样。",
 "盐雾试验与防腐验收": "盐雾只写小时数等于没写——方法、判据、试样状态三样写全，才算能验收。",
 "湿热与凝露防护": "凝露只看一件事：表面温度是不是低于露点——密封越死，越要加透气膜。",
 "高低温与热冲击适应性": "温度循环坏的不是强度，是膨胀差——长件留浮动、粘接别刚性、灌封选软的。",
 "霉菌与生物环境防护": "防霉靠控湿不靠加药——湿度压到 65% 以下，霉菌自己就不来。",
 "环境条件分级与试验要求（GB/T 4798）": "客户只给一个工作温度是常态——贮存、运输、湿度、盐雾都要自己补齐，并写明对应的试验方法。",
 "人体尺寸与百分位取值": "该大的取大、该小的取小——舒服的取中间、安全的取两端，别拿平均身高当设计身高。",
 "操作力与握持设计": "按手最小的那个人校核——手宽 P5 的女工握得住，才是好手柄。",
 "可及性与操作空间设计": "别只看「伸不伸得到」——还要问「扳手转不转得开、戴手套还塞不塞得进」。",
 "边缘与尖角安全设计": "「锐边倒钝」四个字等于没写——给 R 值、给毛刺上限、标明毛刺朝哪一面。",
 "机械安全与风险评估": "先做设计、再做防护、最后才是贴标签——顺序颠倒，标签就成了免责书。",
 "防护装置与安全距离": "网孔和距离必须一起查表——30 mm 的孔就要 850 mm 的距离，孔改小往往比整机加大便宜。",
 "联锁与安全控制系统": "联锁管两件事：开门必须停、关门也不能自己启动——PLd 是算出来的，不是买出来的。",
 "夹手与挤压点防护": "缝要么 6 mm 以下、要么 25 mm 以上——中间那 8～25 mm 就是夹手的坑。",
 "儿童安全与细小零件防护": "小件、电池、磁铁——三样掉一个就召回；能用超声焊就别用螺丝，能用螺丝就别用双面胶。",
 "警示标识与使用说明": "标签是最后一道防线——能改结构的先改结构，贴纸在户外只有一年寿命。",
 "电机选型（直流有刷 / 步进 / 无刷）": "先算转矩转速占空比，再挑电机——堵转电流按额定 5–10 倍留。",
 "电机驱动与调速方式": "驱动按峰值电流选，PWM 上 20kHz，起停要加减速曲线。",
 "电源适配器与电源模块选型": "适配器按峰值功率选、负载率压到七成，证书要按型号核。",
 "电池选型与电池包设计": "选电芯看容量乘 C 值两条线，电池包逃不开 UN 38.3 和分容配对。",
 "电池充放电与保护电路": "充电别超过 4.2V，NTC 要贴电芯上——测板温等于没保护。",
 "线束走向与防护设计": "先算电流再算压降，动力与信号分开走，穿孔必加护套。",
 "连接器的防呆与锁止结构": "颜色不算防呆，键位和针数才算；一次锁之外要有二次锁。",
 "EMC 屏蔽与接地结构": "屏蔽看最大开口尺寸，不看面积；屏蔽层必须环形接地。",
 "保险丝与过流保护器件选型": "保险丝按工作电流七五折选，浪涌大用慢断，直流别用交流的。",
 "继电器与接触器选型": "触点按负载类型打骨折算，安全回路必须上安全继电器。",
 "传感器选型与安装结构": "传感器按标称距离的六七折装，支架要比传感器还刚。",
 "绝缘材料选型与耐压设计": "先看 CTI、耐温、阻燃三个数，再谈爬电距离和耐压。",
 "可靠性预计与 MTBF": "MTBF 是失效率的倒数不是寿命，串联系统短板说了算。",
 "加速寿命试验": "加速前提是机理不变——先摸应力窗口，再谈倍率。",
 "抽样检验与 AQL": "接收不等于批合格——AQL 是过程平均，安全项别抽样。",
 "过程能力与 SPC": "先判受控再算能力；Cp 看设备，Cpk 看对中。",
 "检验规范与限度样板": "写清怎么检、谁签样板——外观标准的边界靠实物锁住。",
 "控制计划（Control Plan）": "控制计划要能追到 PFMEA，反应计划写到谁在多久做什么。",
 "PPAP 与量产件批准": "PPAP 证的是工艺不是零件——等级先跟客户确认，数据量别糊弄。",
 "8D 与质量问题闭环": "D4 写「员工疏忽」等于没做根因；对策要让错误不可能再发生。",
 "测量系统分析（MSA / GR&R）": "先看量具分辨力够不够，再谈 GR&R——零件要挑有差异的。",
 "失效分析流程（FA）": "先记录、再无损、最后开盖；没复现就只能写「最可能」。",
 "产品开发流程（NPI 阶段与门径）": "流程是拿来防亏钱的——每一道门都是趁还便宜的时候把问题改掉。",
 "需求分析与设计规格书": "规格书里没有测量方法的指标，等于没写。",
 "设计评审与阶段门评审": "评审不是看做得怎样，是看哪里会炸——清单、到人、跟到闭环。",
 "图文档管理与版本控制": "一张图号只能有一个活版本——旧图不回收，早晚按旧图做废一批。",
 "图纸发布与审核检查": "图纸是合同——材料只写名称不写标准号，等于让供应商自由发挥。",
 "试产到量产的移交": "试产要在量产线上用量产的人和工装做——不然试出来的是假象。",
 "供应商技术交底与打样跟进": "交底要让供应商复述一遍——他理解错了，损失是你的。",
 "设计问题闭环与经验沉淀": "同一个坑踩两次，不是运气差，是没把结论写成能搜到的话。",
 "专利规避与创新设计": "侵权判定看权利要求不看长相——少一个特征就不落入，改参数往往最便宜。",
 "技术文件与说明书编制": "说明书是产品的一部分——警示语要写在动作旁边，不是最后一页。",
 "钣金下料方式对比与选择": "打样激光、批量冲模、网孔 NCT、条料剪床——按批量 × 形状 × 料厚 × 交期选。",
 "数控冲床 NCT 加工": "NCT 会成形、激光只会切；最小孔 1.0–1.3t、平行边距 1.5t、避开夹钳死区。",
 "折弯机与折弯模具（V 槽与折弯力）": "V 定三件事：内 R、最小直边、吨位；F≈65t²/V，铝 ×0.65 不锈钢 ×1.6。",
 "钣金折弯顺序与工艺路线": "对下一刀不干涉的先折；先内后外、先小后大、先特殊后普通。",
 "钣金局部成形（凸包·压线·止裂槽）": "凸包高不过 6T；压线 W=T 深 0.3t；止裂槽宽过 1.5T。",
 "钣金异形展开放样（天圆地方·弯头·三通）": "πD 十二等分、求实长、光滑连曲线；样板按中性层、收缩留 2mm。",
 "钣金毛刺与去毛刺": "毛刺按表面处理分档验收：喷涂可留、电镀不刮手、不处理全清。",
 "钣金件报价与成本核算": "料 ×1.15 损耗、工序单价 × 数量、样品 ×3——漏掉二次加工必亏。",
 "钣金折弯边高与干涉检查": "直边不过 2t、不过 V 的一半、不过 2.5mm——三个下限取最大。",
 "钣金件常用结构形式": "薄板要刚度先压筋不加厚；要螺纹先翻边再压铆；要散热开百叶窗。",
 "压铸件壁厚均一与掏料减重": "压铸壁厚 2–3mm 最稳——厚位掏料加筋网，超 4mm 必缩孔气孔。",
 "压铸件气孔与缩孔规避": "气孔是压铸的天性（约占体积 0.1–1%）——靠控壁厚避热节预防，别指望事后挽救。",
 "压铸模抽芯与分型面约束": "侧孔凹槽必带滑块抽芯——分型线藏非外观面，顶针与浇口残留先在图上留位。",
 "挤压截面壁厚均衡设计": "截面壁厚接近、对称布置——厚薄差大流速不均，型材必扭。",
 "型材截面功能结构": "卡槽、卡口、止口、散热鳍一次挤出——装配特征长在截面上，零装配成本。",
 "型材扭拧与粗晶缺陷规避": "扭拧弯曲查模具流速，粗晶环查挤压温度——氧化前控工艺，别等成品。",
 "硬质阳极氧化": "膜厚 25–50μm 硬而脆——锐边易崩边，配合间隙按膜厚一半预留。",
 "导电氧化（铬化 / 钝化）": "膜薄（<1μm）又导电——室内短期防护用，耐蚀远不如阳极氧化。",
 "喷砂 / 抛丸": "喷砂为附着力与去氧化皮——薄壁（<1.5mm）件降气压、拉开距离防变形。",
 "电泳涂装": "电场沉积，内腔背面全覆盖（10–25μm）——耐蚀好但色系少，基材必须导电。",
 "化学镀镍": "无电解也能均匀镀进深孔内腔（偏差约 ±10%）——硬度高，多外协专业厂做。",
 "表面处理膜厚与公差的关系": "膜厚吃公差——氧化约涨膜厚一半、喷涂几乎全涨，配合面留量或遮蔽。",
 "后处理的遮蔽（Masking）设计": "螺纹、导电面、配合面必须遮蔽——胶塞与治具比手贴胶带可靠。",
 "表面处理成本与起订量": "阳极约 3–15 元/件、喷涂约 2–10 元/件——小批量吃亏在起步价。",
 "表面处理的前处理（脱脂 / 除锈 / 活化）": "掉漆缩孔先查前处理——水膜连续性试验一测便知油污除净没。",
 "攻丝（机牙螺纹）底孔与深度": "底孔=公称直径−螺距（M3 打 φ2.5）——盲孔再多留 3–5 牙。",
 "螺纹啮合长度与强度": "钢对钢 1 倍径、对铝 1.5 倍、对塑料 2–3 倍——啮合不足必滑牙，比扭矩更关键。",
 "螺纹的工序顺序与保护": "攻丝排在热处理后、喷涂前——喷涂会堵牙，遮蔽或镀后回丝兜底。",
 "铣削 / CNC 后加工面": "CNC 面能到 ±0.05mm——装夹次数涨成本，内直角做不出（R≥1.5mm）。",
 "去毛刺与倒角": "锐边倒钝 0.2–0.5mm、螺纹口倒 0.5×45°——毛刺划伤、干涉还漏镀。",
 "拉铆螺母（单面操作）": "封闭型材与管件的螺纹解——单面拉铆，防水选密封型，按直径校核啮合。",
 "铆接（实心铆 / 抽芯铆）": "抽芯单面高效不可拆，实心双面强度高——孔比钉径大 0.1–0.2mm。",
 "压铆件的孔径与板厚匹配": "压铆件按板厚选型号——孔大推出力不足，孔小压不进、板鼓包。",
 "去应力退火": "焊接冲压机加后都有内应力——钢 550–650℃、铝 200–300℃ 退掉防缓变。",
 "淬火 + 回火": "淬火提硬度、回火补韧性——变形开裂多发生在尖角与厚薄突变处。",
 "时效处理（铝合金 T5 / T6）": "T6 强度高于 T5——时效后尺寸趋稳仍有微变，精密面留余量。",
 "表面淬火 / 渗碳 / 氮化": "只硬表层：感应 0.5–3、渗碳 0.3–1.5、氮化 0.1–0.5mm——氮化变形最小放最后。",
 "热处理变形与加工余量": "精孔精槽开在热处理之后——顺序反了，变形让尺寸全超差。",
 "后加工工序链与顺序原则": "先成形后热处理、先热处理后精加工、压铆在喷涂前——顺序即良率。",
 "3D 打印工艺选型（SLA / SLS / FDM / MJF）": "SLA 精却脆、尼龙近注塑、FDM 便宜层纹弱——按验证目标选。",
 "CNC 手板（减材手板）": "真材实料铣出来，精度 ±0.05mm——最接近量产件的功能手板，按工时计价。",
 "手板与量产件的差异": "手板装得上别高兴太早——量产注塑有缩水与斜度，卡扣手感完全不同。",
 "手板试装配与干涉检查": "到手先做无螺钉试装——卡扣、止口、螺丝柱、走线一处一处过。",
 "手板的表面处理与外观确认": "手板只能确认颜色方向——手工处理给不了量产的质感一致性。",
 "手板的强度与跌落验证": "同材料同工艺结论才成立——打印件偏保守，CNC 件偏乐观。",
 "复模（硅胶模）的小批量能力": "一套硅胶模 20–50 件，PU 件强度低易黄变——只做 10–100 件验证。",
 "快模（铝模 / 软模）与试模": "铝模成本约钢模 1/3–1/2、寿命几万模次——验证期用，量产仍上钢模。",
 "打样交期与成本结构": "打印按克、CNC 按工时、复模按模加件——交期 2–7 天，先问清计价方式。",
 "小批量（100–1000 件）工艺路线": "百件内复模或打印，千件内快模，再往上钢模——模具摊销决定单价。",
 "装配顺序与防错设计（防呆）": "能装反的结构迟早装反——不对称定位加防呆缺口，靠设计不靠培训。",
 "螺纹紧固扭矩与防松": "扭矩按规格与材料定，塑料柱怕拧裂——防松靠弹垫与螺纹胶，不是拧更紧。",
 "点胶工艺（胶量 / 固化 / 夹具）": "胶量按缝隙体积算、胶路连续才密封——UV 秒级固化怕阴影，硅胶要等 24 小时。",
 "密封与防水装配（O 圈 / 密封胶 / 超声密封）": "O 圈靠 20–30% 压缩量密封——拧更紧只会压裂，超声密封装上就拆不开。",
 "装配后的气密与 IP 验证": "IP 按 GB/T 4208 验——量产用气密检漏替水浸，快且能量化压降。",
 "装配公差链与浮动设计": "单件全合格合不起来是公差链没算——腰形孔与加大孔留浮动量兜底。",
 "拆解与维修性设计（DFR）": "常换件必须单独可拆——螺钉可达、线束可插拔，别拿胶粘盖住维修点。",
 "装配异响与间隙控制": "异响来自间隙与刚性不足——加筋、贴泡棉、控制扣合量三招解决。",
 "手板材料的选择（树脂 / 尼龙 / ABS 板 / 铝）": "树脂看外观、尼龙验功能、ABS 板近量产、铝验强度散热——按目的选料。",
 "压缩弹簧选型（线径 / 圈数 / 刚度）": "刚度与线径四次方成正比——改线径最灵，压缩量别超自由长 40%。",
 "拉伸与扭转弹簧": "拉伸簧有初拉力、扭转簧看力臂——安装空间比压缩弹簧敏感得多。",
 "卡簧（挡圈）与轴向定位": "卡簧只定位、不扛大轴向载荷——槽宽槽深按标准，留卡簧钳空间。",
 "弹簧的导向与预压": "无导向的弹簧受压必侧弯——芯轴或导套加预压，力量才稳不折断。",
 "线材折弯（线径 / 最小弯曲半径）": "最小弯曲半径 1–2 倍线径——端部倒圆去毛刺，防割线与应力集中。",
 "冲压弹片（接触件）": "弹片同时算接触压力（0.3–1N）与疲劳寿命——磷青铜或不锈钢，镀镍镀金保导电。",
 "车削件（轴 / 衬套 / 销）": "轴承位 Ra0.8 以内、公差 g6/h7——自由尺寸别给严公差，成本陡增。",
 "五金件的表面处理与防锈": "高强钢丝电镀后必须去氢——否则氢脆断裂；碳钢镀锌，接触件镀金。",
 "五金件的公差与配合选择": "H7/g6 间隙、H7/n6 过渡、H7/p6 过盈——标准件的公差别自行收紧。",
 "弹性件的寿命与疲劳": "应力幅越小寿命越长——弹簧 1 万次、弹片 3 千到 1 万次，力衰减不超 10–20%。",
 "玻璃成型方式（吹制 / 压制 / 离心）": "压制尺寸准壁厚匀，吹制做深腔球泡——壁厚均匀性压制完胜。",
 "玻璃件的壁厚与圆角设计": "尖角与厚薄突变是应力源——转角全 R、同件壁厚差不超 30%、边缘必磨边。",
 "钢化玻璃与安全要求": "钢化强度提 3–5 倍但不能再加工——切钻磨印全在钢化前完成。",
 "玻璃与金属 / 塑料的装配": "玻璃不能刚性压紧——硅胶或 EVA 垫缓冲，膨胀系数差 2–3 倍要留隙。",
 "玻璃的表面处理（磨砂 / 酸洗 / 丝印）": "磨砂酸洗透光率掉 10–30%——丝印用高温油墨随钢化烧结才耐擦。",
 "光学件方案取舍（注塑 vs 玻璃）": "注塑便宜能带卡扣，玻璃稳定耐高温——批量选注塑，精密光学选玻璃。",
 "玻璃件的公差与外观验收": "玻璃公差宽松（±0.5mm 级）——气泡、结石、划伤、色差四类分级验收。",
 "玻璃件的运输与破损控制": "包装三不：不接触、不悬空、不挤压——ISTA 验证，破损率控 0.3% 以内。",
 "PCBA 的固定与支撑": "支撑点避开元件、间距不超 80mm——板边留 3mm 不布件区给卡槽。",
 "元件高度与散热间距": "板下留元件高（贴片 1–3、插件 5–15mm）——电解电容离热源越远越长寿。",
 "手工焊与回流焊的工艺差异": "回流焊按曲线走、峰值 260℃——手工焊管打样维修，波峰焊管插件批量。",
 "ESD 与接地装配要求": "装配全程防静电——可触金属必须接地（≤0.1Ω），带电件双层绝缘加护罩。",
 "连接器与走线空间": "连接器留 25mm 以上插拔位——走线沿线槽卡扣，避开运动件与热源。",
 "电缆入口与防水接头": "防水接头按线缆外径选——锁紧后做拉伸与气密验证，锁母留旋紧空间。",
 "按键板与指示结构": "手感=行程 0.15–0.5mm + 压力 1–3N + 回弹件——指示灯必须防串光。",
 "弹簧与弹片的常见失效": "断、衰、锈、卡四类失效——查应力集中、疲劳、去氢与导向间隙。",
 "玻璃件的常见结构形式": "球罩吹制、平板压制、曲面板热弯、翻边件卡装——按形状定工艺。",
 "玻璃件的常见缺陷与规避": "气泡结石看熔制、壁厚不均吹制固有、自爆查硫化镍——验收前先约定分级。",
 "电子装配的常见问题": "虚焊、压接、接地断、顶壳、压线五大坑——每条都要结构上预留堵住。",
 "缩水痕（缩痕）与缩孔": "缩痕=补缩不足——肋厚取基板50~80%、垫料2~5mm、保压75~85%。",
 "熔接线（夹水纹）": "熔接线靠浇口位置转移——汇流角>135°、温差<10℃、强度仅10~90%。",
 "注塑件翘曲变形控制": "翘曲源于收缩不均（收缩可达20%）——肉厚过渡3倍、冷却均布。",
 "银纹（料花）与气泡": "银纹按位置辨七类：全件查干燥、浇口查冷料射退、固定查壁厚突变。",
 "塑料铰链（活铰链）": "活铰链寿命靠取向——厚 0.25–0.5mm、长厚比 ≥3:1、浇口垂直转轴。",
 "应力开裂（ESC）与退火去应力": "ESC＝应力×介质——溶剂法90s判定，PS 78℃/PC 160℃退火复测。",
 "模具冷却水路设计": "冷却均不均定翘曲——水径1/4\"~1/2\"、间距3/5mm、模温差≤10℃。",
 "PBT / PET（聚酯）": "GF30 分向放缩、先干燥——流向 0.1-0.3%、横向 0.7-0.9%。"
};

